const rows=$input.all().map(i=>i.json);
if(rows.every(x=>typeof x.pieza_id==='string')) {
 const expected=new Set(['linkedin-editorial-2026-09-29T02-09-44-998Z-1','linkedin-editorial-2026-09-29T02-09-44-998Z-2']);
 if(rows.length!==2||rows.some(x=>!expected.has(x.pieza_id)||x.estado!=='PENDIENTE_REVISION'||typeof x.texto!=='string'||!x.texto.trim()||typeof x.tema!=='string'||!x.tema.trim()||typeof x.idea_visual!=='string'||!x.idea_visual.trim())) throw new Error('Las dos piezas existentes deben tener estado y campos válidos');
 return rows.map(json=>({json}));
}
const r=rows[0];
if(r.stop_reason!=='end_turn') throw new Error('Respuesta incompleta');
let raw=(r.content||[]).filter(b=>b.type==='text').map(b=>b.text).join('\n').trim();
if(raw.startsWith(String.fromCharCode(96).repeat(3))) raw=raw.slice(raw.indexOf('\n')+1).trim();
if(raw.endsWith(String.fromCharCode(96).repeat(3))) raw=raw.slice(0,-3).trim();
const d=JSON.parse(raw);
const brief=$('Brief editorial - editar fuentes').first().json;
const fuentes=new Map(brief.fuentes.map(f=>[f.id,f]));
if(!Array.isArray(d.publicaciones)||d.publicaciones.length!==2) throw new Error('Deben existir exactamente dos borradores');
const prev=$('Leer historial editorial').all().map(i=>i.json);
const norm=s=>String(s||'').normalize('NFKD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,' ').replace(/\s+/g,' ').trim();
const stop=new Set(['para','como','desde','sobre','entre','esta','este','estos','estas','tiene','tienen','dentro','mismo','misma','cada','nivel','somos','estamos','usamos','uso','con','del','las','los','una','uno','que','por','sus','sin']);
const palabras=s=>new Set(norm(s).split(' ').filter(w=>w.length>3&&!stop.has(w)));
const cobertura=(a,b)=>{const x=[...palabras(a)],y=palabras(b);return x.length?x.filter(w=>y.has(w)).length/x.length:0;};
const seenText=new Set(prev.filter(x=>x.texto).map(x=>norm(x.texto)));
const seenIds=new Set(prev.filter(x=>x.pieza_id).map(x=>String(x.pieza_id)));
const tipos=new Set(['caso','educativo']);
return d.publicaciones.map((p,i)=>{
 if(!p||typeof p!=='object') throw new Error('Borrador inválido');
 const texto=typeof p.texto==='string'?p.texto.trim():'';
 const tema=typeof p.tema==='string'?p.tema.trim():'';
 const idea=typeof p.idea_visual==='string'?p.idea_visual.trim():'';
 if(texto.length<600||texto.length>2500||!tema||!idea) throw new Error('Texto, tema o idea visual inválidos');
 if(!tipos.has(p.tipo_contenido)) throw new Error('tipo_contenido inválido');
 if(!Array.isArray(p.fuentes)||!p.fuentes.length||new Set(p.fuentes).size!==p.fuentes.length||p.fuentes.some(id=>!fuentes.has(id))) throw new Error('Fuentes inválidas');
 if(!Array.isArray(p.pendientes)||p.pendientes.some(x=>typeof x!=='string'||!x.trim())) throw new Error('Pendientes inválidos');
 if(!Array.isArray(p.afirmaciones)||!p.afirmaciones.length) throw new Error('Falta trazabilidad de afirmaciones');
 const usadas=new Set();
 for(const a of p.afirmaciones){
  if(!a||typeof a.afirmacion!=='string'||!a.afirmacion.trim()||!fuentes.has(a.fuente_id)) throw new Error('Afirmación sin fuente válida');
  if(!p.fuentes.includes(a.fuente_id)) throw new Error('Fuente de afirmación no declarada');
  if(cobertura(a.afirmacion,fuentes.get(a.fuente_id).hecho)<0.35) throw new Error('Afirmación sin respaldo textual suficiente en la fuente');
  usadas.add(a.fuente_id);
 }
 const personales=texto.split(/(?<=[.!?])\s+|\n+/).map(s=>s.trim()).filter(s=>/\ben antic\b|\bdesarrollamos\b|\boperamos\b|\busamos\b|\bnuestro|\bnuestra|\bla arquitectura es\b|\bel stack que usamos\b|\bla decisi[oó]n de migrar\b/i.test(s));
 if(personales.some(s=>!p.afirmaciones.some(a=>cobertura(s,a.afirmacion)>=0.35))) throw new Error('Afirmación personal del texto sin trazabilidad');
 if(p.fuentes.some(id=>!usadas.has(id))) throw new Error('Fuente declarada sin afirmación asociada');
 const key=norm(texto);
 if(seenText.has(key)) throw new Error('Borrador duplicado: actualizar las fuentes');
 seenText.add(key);
 const pieza_id=brief.lote_id+'-'+(i+1);
 if(seenIds.has(pieza_id)) throw new Error('pieza_id duplicado');
 seenIds.add(pieza_id);
 return {json:{pieza_id,estado:'PENDIENTE_REVISION',tema,texto,evidencia_json:JSON.stringify({fuentes:p.fuentes.map(id=>fuentes.get(id)),afirmaciones:p.afirmaciones,pendientes:p.pendientes,tipo:p.tipo_contenido,revision:'Estructura, referencias, cobertura textual, afirmaciones personales y duplicados comprobados; veracidad final pendiente de revisión humana'}),idea_visual:idea,url_publicada:''}};
});

